def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Get background color (first cell value of row 0)
    bg = grid[0][0]

    # Save the first row pattern
    first_row = grid[0]

    # Find all non-bg positions in first row
    non_bg_positions = []
    for c in range(cols):
        if first_row[c] != bg:
            non_bg_positions.append(c)

    output = []
    for r in range(rows):
        if r % 2 == 0:
            # Even rows: copy first row exactly
            output.append(list(first_row))
        else:
            # Odd rows: alternate rows get values spread from non-bg positions
            new_row = list(bg) * cols

            # Every other odd row gets the spread from first non-bg
            if (r + 1) // 2 % 2 == 1:
                # Pattern 1: value at column + shift
                for c in non_bg_positions:
                    value = first_row[c]
                    if c > 0:
                        new_row[c-1] = value
                    new_row[c] = value
                    if c < cols - 1:
                        new_row[c+1] = value
            else:
                # Pattern 2: just center
                for c in non_bg_positions:
                    value = first_row[c]
                    new_row[c] = value
            output.append(new_row)

    return output
